    beats = {
        { id = "kettle", at = 15, title = "The kettle",
            text = "I hatched in an old kettle on a shed shelf, one of five, out of a pale egg with rusty freckles. The kettle had no lid. The first thing I ever saw was a round piece of sky. I have been telling the sky what to do ever since." },
        { id = "brown", at = 40, title = "The brown year",
            text = "Young robins have no red at all. Speckled brown, top to toe, like a small wet thrush. I asked my father when mine would come. He said when you have ground to stand on. Then he sang over my head, at somebody else." },
        { id = "sent_off", at = 80, title = "Sent off",
            text = "By late summer my own father chased me out of the garden. Robins do. One patch, one bird. I flew to the end of the lane, sat on a wall and sang the only song I had, at nobody. Poor song. Loud, though." },
        { id = "red", at = 140, title = "The first red",
            text = "The red came in that autumn, a feather at a time. I checked in every puddle. So there I was, a breast like a berry and no ground to my name. Nobody had told me that red needs somewhere to stand." },
        { id = "lamp", at = 220, title = "The lamp",
            text = "That winter I roosted in ivy beside a street lamp. The light never went out, so neither did I. I sang half the night to an empty road. Once a window opened and somebody listened to the end. I never saw a face." },
        { id = "spade", at = 320, title = "The spade",
            text = "In spring I found a garden with an old gardener and a spade. Wherever the spade went, worms came up. I followed at the heel, then the boot, then the handle. The gardener never spoke. Whistled, sometimes. Three notes. I answered." },
        { id = "patch", at = 450, title = "The patch",
            text = "I took that garden for my own. Sang from every corner until the others gave up. Gate to apple tree, mine. The gardener dug and I guarded. I thought that was how things would stay. Young birds think so." },
        { id = "shed", at = 600, title = "The spade stands still",
            text = "One spring the spade stayed in the shed. The beds grew over. I kept my rounds and sang at the back door each dawn. I do not know where old gardeners go. I know the whistle stopped, and I went on answering." },
        { id = "holding", at = 800, title = "Holding",
            text = "I held the patch three winters on my own. Sang by the lamp when the nights ran long. A bird can guard an empty garden a good while. Ask me why and I would have said habit. I would have been fibbing." },
        { id = "chair", at = 1050, title = "The chair",
            text = "Then you came out with a chair and no spade. Sat down. Opened a thing full of leaves and turned them over, one by one, slowly, the way soil gets turned. I flew to the handle of the old spade to get a proper look." },
        { id = "turning", at = 1400, title = "Turning over",
            text = "I have watched you turn {total} pages now. No worms come up. Something does, though. I see a change cross your face, the way light crosses a fresh dug bed. I have stopped looking for the worm. I watch the face." },
        { id = "whistle", at = 1800, title = "Three notes",
            text = "Yesterday you whistled over your book, without noticing. Three notes. I answered before I could think. I have held this ground through frost and empty years, singing mine, mine, mine. I had the word wrong, neighbour. The word was ours. I only needed somebody to whistle back." },
    },
}
